def can_divide_consecutive_groups(nums, k):
 from collections import Counter
 if len(nums)%k:return False
 counts=Counter(nums)
 for first in sorted(counts):
  copies=counts[first]
  if copies:
   for value in range(first,first+k):
    if counts[value]<copies:return False
    counts[value]-=copies
 return True

